38→export function findSkillDirs(root: string, opts: FindSkillDirsOptions = {}): string[] {
  const maxDepth = opts.maxDepth ?? DEFAULT_MAX_DEPTH;
40→  const ignore = new Set(opts.ignore ?? DEFAULT_IGNORE);
  const found = new Set<string>();

  function walk(dir: string, depth: number): void {
    if (!existsSync(dir)) return;
    if (isSkillDir(dir)) {
      found.add(resolve(dir));
      return; // leaf: don't descend into a skill's own supporting files
    }
    if (depth >= maxDepth) return;
50→
    let entries;
    try {
      entries = readdirSync(dir, { withFileTypes: true });
    } catch {
      return;
    }
    for (const entry of entries) {
      if (!entry.isDirectory()) continue;
      if (ignore.has(entry.name)) continue;
60→      walk(resolve(dir, entry.name), depth + 1);
    }
  }

  walk(resolve(root), 0);
  return [...found].sort();
}

